package com.amit.jobagent.matching;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @SecurityRequirement(name="basicAuth") public class JobEvaluationController{private final JobEvaluationService service;public JobEvaluationController(JobEvaluationService s){service=s;}@PostMapping("/api/v1/jobs/{id}/evaluate")public ResponseEntity<JobEvaluationResponse>evaluate(@PathVariable UUID id,@RequestParam(defaultValue="false")boolean force){var r=service.submit(id,force);return ResponseEntity.accepted().location(URI.create("/api/v1/job-evaluations/"+r.id())).body(r);}@GetMapping("/api/v1/jobs/{id}/evaluations")public List<JobEvaluationResponse>list(@PathVariable UUID id){return service.list(id);}@GetMapping("/api/v1/job-evaluations/{id}")public JobEvaluationResponse get(@PathVariable UUID id){return service.get(id);}}
